/// Lines waiting for the drain thread.
pub(super) const CAPACITY: usize = 32;

#[derive(Default)]
struct Queue {
    lines: VecDeque<String>,
    dropped: u64,
}

/// Queues one line; never blocks.
pub(super) fn report(&self, line: String) {
    let mut q = self.lock();
    if q.lines.len() >= CAPACITY {
        q.dropped += 1;
        return;
    }
    q.lines.push_back(line);
    self.cv.notify_one();
}

/// Drains the queue into `sink` on a helper thread; write errors are ignored.
pub(super) fn start(self: &Arc<Self>, mut sink: impl Write + Send + 'static) -> io::Result<()> {
    let diag = self.clone();
    channel::helper("diagnostics", move || {
        loop {
            let (line, dropped) = diag.next();
            let _ = writeln!(sink, "hugr-omni-supervisor: {line}");
            if dropped > 0 {
                let _ = writeln!(
                    sink,
                    "hugr-omni-supervisor: {dropped} more diagnostic line(s) were dropped"
                );
            }
            let _ = sink.flush();
        }
    })

/// The next line, and the drops counted since the last one.
fn next(&self) -> (String, u64) {
    let mut q = self.lock();
    loop {
        if let Some(line) = q.lines.pop_front() {
            return (line, std::mem::take(&mut q.dropped));
        }
        q = self.cv.wait(q).unwrap_or_else(PoisonError::into_inner);
    }

/// The Job's live members, minus `exclude` (the root once it exited).
pub(super) fn list(job: &OwnedHandle, exclude: Option<u32>) -> io::Result<Vec<ProcEntry>> {
    let candidates: Vec<u32> = job::member_pids(job)?
        .into_iter()
        .filter(|&p| Some(p) != exclude)
        .collect();
    of(job, &candidates)
}

/// The live members among `candidates`. `ppid` is set only when the parent is listed and was created no
/// later than the child (a parent pid reused by a younger member is not the parent).
pub(super) fn of(job: &OwnedHandle, candidates: &[u32]) -> io::Result<Vec<ProcEntry>> {
    let mut held = HashMap::new();
    for &pid in candidates {
        if let Probe::Member(h) = job::probe(job, pid)?
            && !job::exited(&h)
        {
            held.insert(pid, h);
        }
    }
    let snap = snapshot(&held)?;
    // Liveness is confirmed after the snapshot; a member absent from it exited meanwhile.
    let mut live = HashMap::new();
    for (pid, h) in &held {
        if let Some((ppid, name)) = snap.get(pid).filter(|_| !job::exited(h)) {
            live.insert(*pid, (*ppid, name.clone(), created(h)?));
        }
    }
    Ok(live
        .iter()
        .map(|(&pid, (ppid, name, born))| ProcEntry {
            pid,
            ppid: live.get(ppid).filter(|parent| parent.2 <= *born).map(|_| *ppid),
            name: (!name.is_empty()).then(|| name.clone()),
        })
        .collect())

fn created(process: &OwnedHandle) -> io::Result<u64> {
    let (mut c, mut e, mut k, mut u) = (
        FILETIME::default(),
        FILETIME::default(),
        FILETIME::default(),
        FILETIME::default(),
    );
    // SAFETY: a process handle with query access and four valid out pointers.
    if unsafe { GetProcessTimes(process.as_raw_handle(), &mut c, &mut e, &mut k, &mut u) } == 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(u64::from(c.dwHighDateTime) << 32 | u64::from(c.dwLowDateTime))

// SAFETY: `entry` has `dwSize` set, as both calls require.
let mut ok = unsafe { Process32FirstW(snap.as_raw_handle(), &mut entry) };
while ok != 0 {
    if held.contains_key(&entry.th32ProcessID) {
        let len = entry
            .szExeFile
            .iter()
            .position(|&c| c == 0)
            .unwrap_or(entry.szExeFile.len());
        let name = String::from_utf16_lossy(entry.szExeFile.get(..len).unwrap_or_default());
        found.insert(entry.th32ProcessID, (entry.th32ParentProcessID, name));
    }
    // SAFETY: as above.
    ok = unsafe { Process32NextW(snap.as_raw_handle(), &mut entry) };
}
let err = io::Error::last_os_error();
if err.raw_os_error() != Some(ERROR_NO_MORE_FILES as i32) {
    return Err(err);
}
Ok(found)

/// A new anonymous, non-inheritable Job whose last handle closing kills every member.
pub(super) fn create() -> io::Result<OwnedHandle> {
    // SAFETY: null attributes (not inheritable) and no name; the result is checked for null.
    let job = unsafe { CreateJobObjectW(std::ptr::null(), std::ptr::null()) };
    // SAFETY: `job` is null or a fresh handle owned by nobody else.
    let job =
        OwnedHandle::try_from(unsafe { HandleOrNull::from_raw_handle(job) }).map_err(|_| io::Error::last_os_error())?;
    let mut limits = JOBOBJECT_EXTENDED_LIMIT_INFORMATION::default();
    // Only KILL_ON_JOB_CLOSE: never JOB_OBJECT_LIMIT_BREAKAWAY_OK or SILENT_BREAKAWAY_OK.
    limits.BasicLimitInformation.LimitFlags = JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE;
    // SAFETY: `limits` is the structure this information class expects, with its exact size.
    let ok = unsafe {
        SetInformationJobObject(
            job.as_raw_handle(),
            JobObjectExtendedLimitInformation,
            (&raw const limits).cast(),
            size_of::<JOBOBJECT_EXTENDED_LIMIT_INFORMATION>() as u32,
        )
    };
    if ok == 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(job)

/// Live members, or `None` when the Job cannot be queried (unknown is never taken for empty).
pub(super) fn active(job: &OwnedHandle) -> Option<u32> {
    counts(job).map(|(active, _)| active)
}

/// (live members, every process ever associated with the Job, child Jobs included), or `None`.
pub(super) fn counts(job: &OwnedHandle) -> Option<(u32, u32)> {
    let mut info = JOBOBJECT_BASIC_ACCOUNTING_INFORMATION::default();
    // SAFETY: `info` is the structure this information class expects, with its exact size.
    let ok = unsafe {
        QueryInformationJobObject(
            job.as_raw_handle(),
            JobObjectBasicAccountingInformation,
            (&raw mut info).cast(),
            size_of::<JOBOBJECT_BASIC_ACCOUNTING_INFORMATION>() as u32,
            std::ptr::null_mut(),
        )
    };
    (ok != 0).then_some((info.ActiveProcesses, info.TotalProcesses))
}

/// Forced stop: every member, at once.
pub(super) fn terminate(job: &OwnedHandle) {
    // SAFETY: a valid Job handle. A failure leaves the members alive; `Tree::settle` repeats the pass until
    // the Job is empty.
    unsafe { TerminateJobObject(job.as_raw_handle(), KILLED) };

/// The pids the Job lists now. An error means "unknown", never "none".
pub(super) fn member_pids(job: &OwnedHandle) -> io::Result<Vec<u32>> {
    let header = size_of::<JOBOBJECT_BASIC_PROCESS_ID_LIST>() - size_of::<usize>();
    let mut room = 64usize;
    // The Job can grow between the size query and the next call: a few retries, then an error.
    for _ in 0..4 {
        // usize-aligned buffer: the header, then `room` process ids.
        let mut buf = vec![0usize; header.div_ceil(size_of::<usize>()) + room];
        let bytes = u32::try_from(buf.len() * size_of::<usize>()).map_err(io::Error::other)?;
        // SAFETY: `buf` is writable for `bytes` bytes and aligned for the structure.
        let ok = unsafe {
            QueryInformationJobObject(
                job.as_raw_handle(),
                JobObjectBasicProcessIdList,
                buf.as_mut_ptr().cast(),
                bytes,
                std::ptr::null_mut(),
            )
        };
        let err = io::Error::last_os_error();
        // SAFETY: the buffer starts with the structure's header (written by the call, or still zeroed).
        let list = unsafe { &*buf.as_ptr().cast::<JOBOBJECT_BASIC_PROCESS_ID_LIST>() };
        let (assigned, listed) = (
            list.NumberOfAssignedProcesses as usize,
            list.NumberOfProcessIdsInList as usize,
        );
        if ok != 0 && listed == assigned {
            let ids = buf.get(header.div_ceil(size_of::<usize>())..).unwrap_or_default();
            return Ok(ids.iter().take(listed).map(|&p| p as u32).collect());
        }
        if ok == 0 && err.raw_os_error() != Some(ERROR_MORE_DATA as i32) {
            return Err(err);
        }
        room = assigned.max(room) + 16;
    }
    Err(io::Error::other("the Job kept growing while it was listed"))

/// What a pid names now, as seen from `job`.
pub(super) enum Probe {
    /// No process has this pid: whatever had it is gone.
    Gone,
    /// The pid names a process outside the Job: it was reused, so the member that had it is gone.
    Outside,
    /// A process of the Job, held open (its pid cannot be reused while the handle lives).
    Member(OwnedHandle),
}

/// Opens `pid` and checks it against `job`. Any other failure is an error: unknown, never gone.
pub(super) fn probe(job: &OwnedHandle, pid: u32) -> io::Result<Probe> {
    let Some(h) = open(pid)? else { return Ok(Probe::Gone) };
    let mut inside = 0;
    // SAFETY: valid process and Job handles and a valid out pointer.
    if unsafe { IsProcessInJob(h.as_raw_handle(), job.as_raw_handle(), &mut inside) } == 0 {
        return Err(io::Error::last_os_error());
    }
    Ok(if inside != 0 { Probe::Member(h) } else { Probe::Outside })
}

/// Whatever had `pid` is certainly gone: no process has it, or the one that has it now has exited (a live
/// process keeps its pid, so an exited holder means the original is gone either way).
pub(super) fn certainly_gone(pid: u32) -> bool {
    match open(pid) {
        Ok(None) => true,
        Ok(Some(h)) => exited(&h),
        Err(_) => false,
    }

/// Call only once the Job is empty. First flushes the port (everything queued before the marker was
/// posted while members existed), then reconciles the notifications received with the Job's own count of
/// processes (a lost notification makes the proof Unknown), then probes every pid recorded, and every pid
/// the Job still lists.
pub(super) fn prove(&self, id: u64, job: &OwnedHandle) -> Proof {
    {
        let mut records = self.lock();
        let Some(rec) = records.get_mut(&id) else {
            return Proof::Unknown("the tree has no member record".into());
        };
        match rec.flush {
            Flush::Seen => {}
            Flush::Posted => return Proof::Pending("the completion port is not flushed yet".into()),
            Flush::NotPosted => {
                // SAFETY: a valid port; the packet carries plain integers, no OVERLAPPED is dereferenced.
                let posted = unsafe {
                    PostQueuedCompletionStatus(
                        self.port.as_raw_handle(),
                        0,
                        MARKER,
                        id as usize as *const OVERLAPPED,
                    )
                };
                if posted == 0 {
                    return Proof::Unknown(format!("flush marker: {}", io::Error::last_os_error()));
                }
                rec.flush = Flush::Posted;
                return Proof::Pending("the completion port is not flushed yet".into());
            }
        }
    }
    let Some((_, total)) = job::counts(job) else {
        return Proof::Unknown("the Job's accounting cannot be read".into());
    };
    let notified = self.lock().get(&id).map_or(0, |r| r.notified);
    if notified != u64::from(total) {
        return Proof::Unknown(format!(
            "lost job notification: {notified} of the Job's {total} processes were reported"
        ));
    }
    let listed = match job::member_pids(job) {
        Ok(listed) => listed,
        Err(e) => return Proof::Unknown(format!("the Job's members cannot be listed: {e}")),
    };

let mut gone = Vec::new();
for pid in pids {
    #[cfg(test)]
    if *self.blind.lock().unwrap_or_else(PoisonError::into_inner) == Some(pid) {
        return Proof::Unknown(format!("pid {pid} cannot be inspected (test)"));
    }
    match job::probe(job, pid) {
        Ok(Probe::Gone | Probe::Outside) => gone.push(pid),
        Ok(Probe::Member(h)) if job::exited(&h) => gone.push(pid),
        Ok(Probe::Member(_)) => return Proof::Pending(format!("pid {pid} is still exiting")),
        Err(e) => return Proof::Unknown(format!("pid {pid} cannot be inspected: {e}")),
    }
}
if let Some(rec) = self.lock().get_mut(&id) {
    rec.pids.retain(|p| !gone.contains(p));
}
Proof::Gone

/// The port's reader. Notifications for a tree that is not recorded (never, or no longer) are ignored.
fn serve(&self, inbox: &Inbox) {
    loop {
        let (mut msg, mut key, mut value) = (0u32, 0usize, std::ptr::null_mut::<OVERLAPPED>());
        // SAFETY: a valid port and valid out pointers; job and marker packets carry plain integers.
        let ok = unsafe {
            GetQueuedCompletionStatus(self.port.as_raw_handle(), &mut msg, &mut key, &mut value, INFINITE)
        };
        if ok == 0 {
            return; // the port is gone: proofs stay pending, and `Tree::settle`'s bound answers the Stops
        }
        let (id, pid) = if key == MARKER {
            (value as usize as u64, 0)
        } else {
            (key as u64, value as usize as u32)
        };
        let mut records = self.lock();
        let Some(rec) = records.get_mut(&id) else { continue };
        match (key == MARKER, msg) {
            (true, _) => rec.flush = Flush::Seen,
            (false, MSG_NEW_PROCESS) => {
                #[cfg(test)]
                if self.suppress.swap(false, std::sync::atomic::Ordering::SeqCst) {
                    continue;
                }
                rec.notified += 1;
                rec.pids.insert(pid);
                if rec.pids.len() > rec.sweep_at.max(SWEEP_FROM) {
                    rec.pids.retain(|&p| !job::certainly_gone(p));
                    rec.sweep_at = 2 * rec.pids.len();
                }
                continue;
            }
            (false, MSG_ACTIVE_PROCESS_ZERO) => {}
            _ => continue,
        }
        drop(records);
        inbox.event(Event::Settle { id });
    }

/// One turn of the loop: due deadlines, then one event or request. `Some` = exit with that code.
fn step(&mut self) -> Option<ExitCode> {
    let now = Instant::now();
    self.enforce(now);
    if let Some(bound) = self.host_gone {
        if self.trees.values().all(|t| t.gone) {
            return Some(ExitCode::SUCCESS);
        }
        if now >= bound {
            return Some(ExitCode::FAILURE);
        }
    }
    let admit = self.host_gone.is_none() && self.out.len() + self.stop_waiters < MAX_REPLIES;
    let item = self.inbox.next(admit, self.wake(now, admit));
    // The wait can be long: deadlines due by now go first, and the item is handled at the time it arrived.
    let now = Instant::now();
    self.enforce(now);
    match item {
        Some(Item::Request(m)) => self.request(m, now),
        Some(Item::Event(Event::Exited { id, code })) => self.exited(id, code, now),
        Some(Item::Event(Event::Settle { id })) => self.settle(id, now),
        Some(Item::Event(Event::HostGone)) => self.host_died(now),
        None => {}
    }
    None

/// Queues `msg`; an overflow (impossible by the accounting in `queues`) ends the channel, never blocks.
fn send(&self, msg: &Msg) {
    match self.out.send(msg) {
        Ok(()) => {}
        Err(Refused::Unencodable) => {
            if let Msg::Processes { req, id, .. } = *msg {
                // A list too large for one frame is an incomplete inventory.
                self.send(&Msg::Ack {
                    req,
                    id,
                    result: Ack::Error,
                });
            } else {
                self.inbox.event(Event::HostGone);
            }
        }
        Err(Refused::Full) => self.inbox.event(Event::HostGone),
    }

/// A tree the host still holds (an unknown or released id is `Ack unknown` for every request).
fn live(&mut self, id: u64) -> Option<&mut Tree> {
    self.trees.get_mut(&id).filter(|t| !t.released)
}

fn spawn(&mut self, s: Spawn) -> Msg {
    let req = s.req;
    let failed = |code, errno, msg| Msg::SpawnFailed { req, code, errno, msg };
    if self.trees.len() >= self.max_trees {
        spawn::discard(&s, self.channel as RawHandle);
        let msg = format!(
            "the supervisor holds its limit of {} trees (alive, or not released yet)",
            self.max_trees
        );
        return failed(FailCode::Io, 0, msg);
    }
    let id = self.next_id;
    self.next_id += 1;
    let members = &self.members;
    let root = match spawn::spawn(&s, self.channel as RawHandle, |job| members.watch(id, job)) {
        Ok(root) => root,
        Err(f) => {
            members.forget(id);
            return failed(f.code, f.errno, f.msg);
        }
    };
    let (pty, ends) = root.pty.map_or((None, None), |(p, e)| (Some(p), Some(e)));
    let exit_handle = root.process.try_clone();
    let tree = Tree::new(id, root.pid, root.process, root.job, pty, s.grace_ms);
    // Rollback on failure: dropping `tree` closes its Job, which ends the root.
    let watched = exit_handle.and_then(|h| {
        watch(h, &self.inbox, move |h| Event::Exited {
            id,
            code: tree::exit_code(h),
        })
    });
    if let Err(e) = watched {
        members.forget(id);
        return failed(FailCode::Io, 0, format!("exit watch: {e}"));
    }
    let pid = tree.pid;
    self.trees.insert(id, tree);
    // The host pulls these out with DUPLICATE_CLOSE_SOURCE; they are never touched here again.
    let pty_ends = ends.map_or([0; 2], |e| {
        use std::os::windows::io::IntoRawHandle;
        [e.output.into_raw_handle() as u64, e.input.into_raw_handle() as u64]
    });
    Msg::Spawned { req, id, pid, pty_ends }
}

/// Every tree gets a `Stop` with its own grace, counted from now; the supervisor exits once all are
/// gone, or at the latest deadline plus slack (exiting closes the remaining Jobs, which ends their members).
fn host_died(&mut self, now: Instant) {
    if self.host_gone.is_some() {
        return;
    }
    self.inbox.close();
    self.out.close();
    let mut last = now;
    for t in self.trees.values_mut().filter(|t| !t.gone) {
        t.stop(None, t.grace_ms, now);
        last = last.max(t.deadline().unwrap_or(now));
    }
    self.host_gone = Some(last + HOST_DEATH_SLACK);
    self.next_poll = now;
}

/// Decoded requests waiting for the owner thread.
const MAX_REQUESTS: usize = 64;
/// Replies owed (frames not yet written + `Stop` waiters) at or above which no request is admitted.
pub(super) const MAX_REPLIES: usize = 1024;
/// Tree records (alive, or gone but not released); a `Spawn` beyond it is refused (`docs/protocol.md`).
pub(super) const MAX_TREES: usize = 4096;
/// Request replies, one `Exited` per tree, and `Ready`.
const CAPACITY: usize = MAX_REPLIES + MAX_TREES + 1;

pub(super) fn event(&self, event: Event) {
    let mut q = self.lock();
    if matches!(event, Event::HostGone) {
        if q.host_gone {
            return;
        }
        q.host_gone = true;
    }
    q.events.push_back(event);
    self.owner.notify_one();
}

/// Blocks while the inbox is full; `false` once the host is gone.
pub(super) fn request(&self, msg: Msg) -> bool {
    let mut q = self.lock();
    while q.requests.len() >= MAX_REQUESTS && !q.closed {
        q = self.reader.wait(q).unwrap_or_else(PoisonError::into_inner);
    }
    if q.closed {
        return false;
    }
    q.requests.push_back(msg);
    self.owner.notify_one();
    true

/// The next event, else (if `admit`) the next request, waiting until `until`. `None` on timeout, or when
/// the writer made progress (the caller recomputes `admit`).
pub(super) fn next(&self, admit: bool, until: Option<Instant>) -> Option<Item> {
    let mut q = self.lock();
    loop {
        if let Some(e) = q.events.pop_front() {
            return Some(Item::Event(e));
        }
        if admit && let Some(m) = q.requests.pop_front() {
            self.reader.notify_one();
            return Some(Item::Request(m));
        }
        if q.progress {
            q.progress = false;
            return None;
        }
        q.waiting = true;
        q = match until {
            None => self.owner.wait(q).unwrap_or_else(PoisonError::into_inner),
            Some(t) => {
                let Some(left) = t.checked_duration_since(Instant::now()).filter(|d| !d.is_zero()) else {
                    q.waiting = false;
                    return None;
                };
                self.owner
                    .wait_timeout(q, left)
                    .unwrap_or_else(PoisonError::into_inner)
                    .0
            }
        };
        q.waiting = false;
    }

/// Queues `msg`, never blocking. After `close` frames are dropped.
pub(super) fn send(&self, msg: &Msg) -> Result<(), Refused> {
    let mut frame = Vec::new();
    omni_proto::encode(msg, &mut frame).map_err(|_| Refused::Unencodable)?;
    let mut q = self.lock();
    if q.closed {
        return Ok(());
    }
    if q.frames.len() + q.in_flight >= CAPACITY {
        return Err(Refused::Full);
    }
    q.frames.push_back(frame);
    self.cv.notify_one();
    Ok(())
}

/// Frames not yet written, including the batch being written.
pub(super) fn len(&self) -> usize {
    let q = self.lock();
    q.frames.len() + q.in_flight
}

pub(super) fn close(&self) {
    let mut q = self.lock();
    q.closed = true;
    q.frames.clear();
    self.cv.notify_all();
}

/// Every queued frame as one write (still counted until `written`); `None` once closed.
pub(super) fn take(&self) -> Option<Vec<u8>> {
    let mut q = self.lock();
    loop {
        if q.closed {
            return None;
        }
        if !q.frames.is_empty() {
            q.in_flight = q.frames.len();
            return Some(q.frames.drain(..).flatten().collect());
        }
        q = self.cv.wait(q).unwrap_or_else(PoisonError::into_inner);
    }
}

/// The batch from `take` was written.
pub(super) fn written(&self) {
    self.lock().in_flight = 0;
}

/// Starts `s`. `channel` is the host pipe, which a transferred handle may never be. `watch` sees the Job
/// before any process exists in it.
pub(super) fn spawn(
    s: &Spawn,
    channel: RawHandle,
    watch: impl FnOnce(&OwnedHandle) -> io::Result<()>,
) -> Result<Root, Failure> {
    let stdio = take_stdio(s, channel)?;
    let program = text(&s.program, "program")?;
    let argv = s
        .argv
        .iter()
        .map(|a| text(a, "argument"))
        .collect::<Result<Vec<_>, _>>()?;
    let Some((argv0, args)) = argv.split_first() else {
        return Err(invalid("argv is empty"));
    };
    let program_path = PathBuf::from(OsString::from_wide(&program));
    if !program_path.is_absolute() {
        return Err(invalid(format!(
            "program {} is not an absolute path",
            program_path.display()
        )));
    }
    let cwd = text(&s.cwd, "cwd")?;
    let cwd_path = PathBuf::from(OsString::from_wide(&cwd));
    match std::fs::metadata(&cwd_path) {
        Ok(m) if m.is_dir() => {}
        Ok(_) => {
            return Err(os_failure(
                &cwd_path.display().to_string(),
                &io::Error::from_raw_os_error(ERROR_DIRECTORY as i32),
            ));
        }
        Err(e) => {
            return Err(Failure {
                code: FailCode::BadCwd,
                ..os_failure(&cwd_path.display().to_string(), &e)
            });
        }
    }

let verbatim = match &s.verbatim {
    Some(tail) => Some(text(tail, "the verbatim command line")?),
    None => None,
};
let batch = is_batch(&program_path).map_err(|e| os_failure("program path", &e))?;
// A verbatim line (amendment WP8b) goes to the named program as it is: never with arguments to quote, and never
// to a batch file, which would need a `cmd.exe` the caller did not name.
if verbatim.is_some() && batch {
    return Err(invalid(
        "a verbatim command line cannot start a batch file; name cmd.exe as the program",
    ));
}
if verbatim.is_some() && !args.is_empty() {
    return Err(invalid("a verbatim command line takes argv[0] alone"));
}
// A batch file never reaches CreateProcessW by name (it would start cmd.exe with our unescaped line):
// it runs as `cmd.exe /c` with std's batch quoting, or is refused.
let (app, line) = if batch {
    if !program_path.is_file() {
        let e = io::Error::from_raw_os_error(ERROR_FILE_NOT_FOUND as i32);
        return Err(os_failure(&program_path.display().to_string(), &e));
    }
    // cmd.exe cannot open a verbatim path: std's plain spelling, or a refusal.
    (
        cmd_exe().map_err(|e| os_failure("system directory", &e))?,
        cmdline::user_path(&program).and_then(|script| cmdline::bat(&script, args)),
    )
} else {
    let line = match &verbatim {
        Some(tail) => cmdline::verbatim(argv0, tail),
        None => cmdline::exe(argv0, args),
    };
    (program, line)
};
let mut line = line.map_err(invalid)?;
line.push(0);
let env = env_block(&s.env)?;
let job = job::create().map_err(|e| os_failure("job", &e))?;
watch(&job).map_err(|e| os_failure("job completion port", &e))?;
// A terminal root: the ConPTY path is laid out step by step in `pty_windows`; `create` below is its step 5.
let pty = match s.pty {
    Some((cols, rows)) => Some(pty_windows::create(cols, rows).map_err(|e| match e.kind() {
        io::ErrorKind::InvalidInput => invalid(e.to_string()),
        _ => os_failure("terminal", &e),
    })?),
    None => None,
};
let pc = pty.as_ref().map(|(p, _)| p.handle());
match create(&app, &mut line, &env, &cwd, &job, stdio.as_ref(), pc) {
    Ok((pid, process)) => Ok(Root { pid, process, job, pty }),
    Err(e) => {
        if let Some((p, _)) = pty {
            p.close(Instant::now());
        }
        Err(os_failure("CreateProcessW", &e))
    }

/// Takes ownership of each distinct transferred pipe exactly once (the host gave it to this process for this
/// spawn), then checks the slots. A repeated value, or a missing or extra handle, is refused, and every handle
/// taken is closed on that path. A value that is not a pipe, or is the channel, is not ours to close.
fn take_stdio(s: &Spawn, channel: RawHandle) -> Result<Option<Stdio>, Failure> {
    let mut i = 0;
    let [stdin, stdout, stderr] = s.handles.map(|v| {
        let first = !s.handles.iter().take(i).any(|&o| o == v);
        i += 1;
        let h = v as usize as RawHandle;
        // SAFETY: GetFileType only reads the handle's type; an invalid value gives FILE_TYPE_UNKNOWN.
        let pipe = v != 0 && first && h != channel && unsafe { GetFileType(h as HANDLE) } == FILE_TYPE_PIPE;
        // SAFETY: a pipe handle the host duplicated into this process for this spawn; owned from here on.
        pipe.then(|| unsafe { OwnedHandle::from_raw_handle(h) })
    });
    let given = s.handles.map(|v| v != 0);
    let unusable =
        given.iter().filter(|&&g| g).count() != [&stdin, &stdout, &stderr].iter().filter(|h| h.is_some()).count();
    let wanted = match s.pty {
        Some(_) => [false; 3],
        None => [s.stdin == Slot::Pipe, true, s.stderr == Slot::Pipe],
    };
    if unusable || given != wanted {
        return Err(invalid(format!("handles {:?} do not match the stdio slots", s.handles)));
    }
    let (Some(stdout), None) = (stdout, s.pty) else {
        return Ok(None);
    };
    let stdin = match stdin {
        Some(pipe) => pipe,
        None => open_nul().map_err(|e| os_failure("NUL", &e))?,
    };
    Ok(Some(Stdio { stdin, stdout, stderr }))

/// `KEY=VALUE\0...\0`, sorted by name ignoring ASCII case (the order Windows documents for the block).
fn env_block(env: &[(Vec<u8>, Vec<u8>)]) -> Result<Vec<u16>, Failure> {
    let mut vars = Vec::with_capacity(env.len());
    for (k, v) in env {
        let key = text(k, "environment name")?;
        // A leading `=` is legal (the hidden per-drive `=C:` variables); one anywhere else is not.
        if key.is_empty() || key.iter().skip(1).any(|&c| c == u16::from(b'=')) {
            return Err(invalid(format!(
                "environment name {:?} is empty or contains `=`",
                String::from_utf16_lossy(&key)
            )));
        }
        vars.push((key, text(v, "environment value")?));
    }
    let upper = |c: &u16| if (97..=122).contains(c) { c - 32 } else { *c };
    vars.sort_by(|a, b| a.0.iter().map(upper).cmp(b.0.iter().map(upper)));
    let mut block = Vec::new();
    for (k, v) in vars {
        block.extend(k);
        block.push(u16::from(b'='));
        block.extend(v);
        block.push(0);
    }
    if block.is_empty() {
        block.push(0);
    }
    block.push(0);
    Ok(block)
